 37	function nowId() {
 38	  const d = new Date();
 39	  const pad = (n: number) => String(n).padStart(2, "0");
 40	  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}_${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
 41	}
 42	
 43	function trimTrailingEmptyLines(lines: string[]) {
 44	  let end = lines.length;
 45	  while (end > 0 && lines[end - 1] === "") {
 46	    end -= 1;
 47	  }
 48	  return lines.slice(0, end);
 49	}
 50	
 51	function dumpPlainRange(term: TerminalType, startY: number, endYExclusive: number) {
 52	  const lines: string[] = [];
 53	  const buffer = term.buffer.active;
 54	  const start = Math.max(0, startY);
 55	  const end = Math.max(start, Math.min(endYExclusive, buffer.length));
 56	  for (let y = start; y < end; y++) {
 57	    const line = buffer.getLine(y);
 58	    lines.push(line ? line.translateToString(true) : "");
 59	  }
 60	  return trimTrailingEmptyLines(lines).join("\n");
 61	}
 62	
 63	function dumpPlainViewport(term: TerminalType) {
 64	  const buffer = term.buffer.active;
 65	  const viewportY = buffer.viewportY ?? buffer.baseY ?? 0;
 66	  return dumpPlainRange(term, viewportY, viewportY + term.rows);
 67	}
 68	
 69	function dumpPlainAll(term: TerminalType) {
 70	  const buffer = term.buffer.active;
 71	  return dumpPlainRange(term, 0, buffer.length);
 72	}
