 78	async function promptLabel(): Promise<string> {
 79	  // 完全退出 raw mode，使用正常的行输入
 80	  if (process.stdin.isTTY) {
 81	    process.stdin.setRawMode(false);
 82	  }
 83	  process.stdin.pause();
 84	  
 85	  // 使用 readline 来读取输入，更可靠
 86	  return new Promise<string>((resolve) => {
 87	    const rl = readline.createInterface({
 88	      input: process.stdin,
 89	      output: process.stdout,
 90	      terminal: true
 91	    });
 92	    
 93	    // 先输出换行，确保提示在新行
 94	    process.stdout.write('\r\n');
 95	    
 96	    rl.question('label> ', (answer: string) => {
 97	      rl.close();
 98	      // 恢复 raw mode
 99	      if (process.stdin.isTTY) {
100	        process.stdin.setRawMode(true);
101	      }
102	      process.stdin.resume();
103	      resolve(answer.trim() || "untitled");
104	    });
105	  });
106	}
